export declare const canvasStyles = "\n/* ---- \u753B\u5E03\u5BB9\u5668\u4E0E\u7F51\u683C\u80CC\u666F ---- */\n.wf-canvas-shell {\n  position: relative;\n  flex: 1;\n  min-width: 0;\n  min-height: 0;\n  display: flex;\n  flex-direction: column;\n  background: var(--wf-bg);\n  overflow: hidden;\n}\n\n.wf-canvas-stage {\n  position: relative;\n  flex: 1;\n  min-height: 0;\n  display: flex;\n  overflow: hidden;\n}\n\n.wf-canvas {\n  flex: 1;\n  min-height: 0;\n  position: relative;\n  overflow: hidden;\n  touch-action: none;\n  user-select: none;\n  background-color: var(--wf-bg);\n  background-image: radial-gradient(circle, var(--wf-border-strong) 1.1px, transparent 1.2px), radial-gradient(circle at 50% 0%, color-mix(in srgb, var(--wf-brand) 6%, transparent), transparent 42%);\n  background-size: 24px 24px, 100% 100%;\n  cursor: grab;\n}\n\n.wf-canvas.is-panning {\n  cursor: grabbing;\n}\n\n/* ---- \u56FE\u821E\u53F0\uFF1A\u8FDE\u7EBF / \u7BAD\u5934 / \u6807\u7B7E ---- */\n.wf-graph__stage {\n  position: absolute;\n  left: 0;\n  top: 0;\n  width: 1px;\n  height: 1px;\n  transform-origin: 0 0;\n  will-change: transform;\n}\n\n.wf-graph__edges {\n  position: absolute;\n  left: 0;\n  top: 0;\n  width: 1px;\n  height: 1px;\n  overflow: visible;\n  pointer-events: none;\n}\n\n.wf-graph__edge {\n  fill: none !important;\n  stroke: var(--wf-flow);\n  stroke-width: 2.6;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n  vector-effect: non-scaling-stroke;\n  filter: drop-shadow(0 0 2px color-mix(in srgb, var(--wf-flow) 30%, transparent));\n  pointer-events: none;\n}\n\n.wf-graph__edge.is-selected {\n  stroke-width: 3.6;\n  filter: drop-shadow(0 0 4px color-mix(in srgb, var(--wf-brand) 58%, transparent));\n}\n\n.wf-graph__edge.is-ctx {\n  stroke: var(--wf-context);\n}\n\n.wf-graph__edge.is-db {\n  stroke: var(--wf-database);\n}\n\n.wf-graph__edge.is-pass {\n  stroke: var(--wf-pass);\n}\n\n.wf-graph__edge.is-fail {\n  stroke: var(--wf-fail);\n}\n\n.wf-graph__edge.is-content {\n  stroke: var(--wf-content);\n}\n\n.wf-arrow-head {\n  fill: var(--wf-flow);\n  stroke: none;\n}\n\n.wf-arrow-head.is-pass {\n  fill: var(--wf-pass);\n}\n\n.wf-arrow-head.is-fail {\n  fill: var(--wf-fail);\n}\n\n.wf-arrow-head.is-content {\n  fill: var(--wf-content);\n}\n\n.wf-graph__edge.is-running {\n  stroke-dasharray: 8 5;\n}\n\n/* \u8FD0\u884C\u4E2D\u9501\u5B9A\u8FDE\u7EBF\uFF08\u5DF2\u5B8C\u6210\u6D41\u7A0B / \u6267\u884C\u4E2D\u8282\u70B9\u5DE6\u5165\u53E3\uFF09\uFF1A\u7070\u5316\u865A\u7EBF + \u4E0D\u53EF\u70B9\u51FB\uFF08\u70B9\u51FB\u4E0D\u9009\u4E2D\u3001\u5C5E\u6027\u680F\u4E0D\u5C55\u5F00\uFF09 */\n.wf-graph__edge.is-locked {\n  stroke: var(--wf-ink-2);\n  stroke-dasharray: 3 4;\n  opacity: .55;\n  filter: none;\n}\n\n.wf-graph__edge-hit {\n  fill: none !important;\n  stroke: transparent;\n  stroke-width: 18;\n  vector-effect: non-scaling-stroke;\n  pointer-events: stroke;\n  cursor: pointer;\n}\n\ng.is-locked .wf-graph__edge-hit {\n  cursor: not-allowed;\n}\n\n.wf-graph__connection {\n  fill: none !important;\n  stroke: var(--wf-brand);\n  stroke-width: 2;\n  stroke-dasharray: 7 5;\n  vector-effect: non-scaling-stroke;\n  pointer-events: none;\n}\n\n.wf-graph__label-bg {\n  fill: var(--wf-layer);\n  stroke: var(--wf-border);\n  stroke-width: 1;\n  vector-effect: non-scaling-stroke;\n}\n\n.wf-graph__label {\n  fill: var(--wf-ink);\n  font-size: 10px;\n  font-weight: 750;\n  text-anchor: middle;\n  dominant-baseline: middle;\n  pointer-events: none;\n}\n\n/* ---- \u8282\u70B9\u5B9A\u4F4D\u4E0E\u63A5\u70B9\uFF08\u5165\u53E3\u84DD / \u51FA\u53E3\u6A59\uFF0Cside \u7531\u4EA4\u6362\u51B3\u5B9A\uFF09 ---- */\n.wf-graph__node {\n  position: absolute;\n  width: 208px;\n  height: 116px;\n  pointer-events: auto;\n  cursor: grab;\n}\n\n.wf-graph__node.is-dragging {\n  cursor: grabbing;\n}\n\n.wf-graph__handle {\n  position: absolute;\n  z-index: 4;\n  top: 50%;\n  width: 13px;\n  height: 13px;\n  padding: 0;\n  border: 2px solid var(--wf-bg);\n  border-radius: 50%;\n  background: var(--wf-brand);\n  transform: translateY(-50%);\n  cursor: crosshair;\n  box-shadow: 0 0 0 1px color-mix(in srgb, var(--wf-brand) 65%, var(--wf-border-strong));\n  transition: transform .14s ease, box-shadow .14s ease;\n}\n\n.wf-graph__handle:hover,\n.wf-graph__handle:focus-visible {\n  transform: translateY(-50%) scale(1.18);\n  box-shadow: 0 0 0 5px color-mix(in srgb, var(--wf-brand) 18%, transparent);\n  outline: 0;\n}\n\n/* \u63A5\u70B9\u5DE6\u53F3\u4F4D\u7F6E\uFF1A\u666E\u901A\u5361\u7247\uFF08\u89D2\u8272/\u6587\u4EF6/\u6570\u636E\u5E93/\u9636\u6BB5/\u865A\u62DF\uFF09\u6309\u4EA4\u6362\u72B6\u6001\u52A8\u6001\u6307\u5B9A side\uFF1B\u534F\u4F5C\u7EC4\u5361\u56FA\u5B9A target/source */\n.wf-graph__handle.is-side-left {\n  left: -6px;\n}\n\n.wf-graph__handle.is-side-right {\n  right: -6px;\n}\n\n/* \u63A5\u70B9\u989C\u8272\u533A\u5206\u5165\u53E3/\u51FA\u53E3\uFF08\u7528\u6237\u6279\u6CE8\uFF1A\u5165\u53E3=\u84DD\u3001\u51FA\u53E3=\u6A59\uFF1B\u4F4D\u7F6E\u7531\u4EA4\u6362\u51B3\u5B9A\uFF0C\u989C\u8272\u6807\u8BC6\u65B9\u5411\uFF09 */\n.wf-graph__handle.is-in {\n  background: var(--wf-port-in);\n}\n\n.wf-graph__handle.is-out {\n  background: var(--wf-port-out);\n}\n\n.wf-graph__handle--target {\n  left: -6px;\n  background: var(--wf-port-in);\n}\n\n.wf-graph__handle--source {\n  right: -6px;\n  background: var(--wf-port-out);\n}\n\n/* ---- \u753B\u5E03\u7F29\u653E\u63A7\u4EF6 ---- */\n.wf-graph__controls {\n  position: absolute;\n  z-index: 8;\n  left: 12px;\n  bottom: 12px;\n  display: grid;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 9px;\n  overflow: hidden;\n  background: var(--wf-layer);\n  box-shadow: 0 8px 20px color-mix(in srgb, var(--wf-ink) 9%, transparent);\n}\n\n.wf-graph__controls button {\n  width: 32px;\n  height: 30px;\n  border: 0;\n  border-bottom: 1px solid var(--wf-border);\n  background: var(--wf-layer-2);\n  color: var(--wf-ink);\n  font-weight: 750;\n}\n\n.wf-graph__controls button:last-child {\n  border-bottom: 0;\n}\n\n.wf-graph__controls button:hover {\n  background: color-mix(in srgb, var(--wf-brand) 10%, var(--wf-layer-2));\n  color: var(--wf-brand);\n}\n\n/* ---- \u8282\u70B9\u5361\u7247\u672C\u4F53\uFF08\u60AC\u505C / \u9009\u4E2D / \u9AD8\u4EAE / \u865A\u62DF\u8282\u70B9 / \u9501\u5B9A\uFF09 ---- */\n.wf-node {\n  width: 100%;\n  height: 100%;\n  padding: 12px 14px;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 12px;\n  background: color-mix(in srgb, var(--wf-layer) 96%, var(--wf-brand) 4%);\n  color: var(--wf-ink);\n  box-shadow: 0 8px 24px color-mix(in srgb, var(--wf-ink) 9%, transparent);\n  transition: border-color .16s ease, box-shadow .16s ease, transform .16s ease;\n  overflow: hidden;\n}\n\n.wf-node:hover {\n  border-color: color-mix(in srgb, var(--wf-brand) 55%, var(--wf-border-strong));\n  box-shadow: 0 12px 30px color-mix(in srgb, var(--wf-ink) 12%, transparent);\n}\n\n.wf-node.is-selected {\n  border-color: var(--wf-brand);\n  box-shadow: 0 0 0 3px color-mix(in srgb, var(--wf-brand) 18%, transparent), 0 12px 30px color-mix(in srgb, var(--wf-ink) 12%, transparent);\n}\n\n.wf-node.is-highlighted {\n  border-color: var(--wf-brand);\n  box-shadow: 0 0 0 3px color-mix(in srgb, var(--wf-brand) 26%, transparent), 0 0 18px color-mix(in srgb, var(--wf-brand) 30%, transparent);\n}\n\n.wf-node.is-proxy {\n  border-style: dashed;\n  border-color: var(--wf-warn);\n}\n\n.wf-node__kind {\n  font-size: 10px;\n  text-transform: uppercase;\n  letter-spacing: .06em;\n  color: var(--wf-ink-2);\n  margin-bottom: 2px;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.wf-node__label {\n  font-weight: 650;\n  font-size: 13px;\n  word-break: break-word;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.wf-node__proxy-badge {\n  flex: none;\n  font-size: 9px;\n  font-weight: 750;\n  color: var(--wf-warn);\n  border: 1px solid var(--wf-warn);\n  border-radius: 999px;\n  padding: 0 5px;\n  line-height: 15px;\n}\n\n/* \u8FD0\u884C\u4E2D\u9501\u5B9A\u89D2\u6807\uFF08\u5DF2\u5B8C\u6210/\u6267\u884C\u4E2D\u8282\u70B9\uFF1B\u4EC5\u63D0\u793A\u4E0D\u53EF\u4FEE\u6539\uFF0C\u8282\u70B9\u4ECD\u53EF\u62D6\u52A8\u79FB\u52A8\uFF09 */\n.wf-node__lock-badge {\n  flex: none;\n  font-size: 9px;\n  line-height: 14px;\n  opacity: .75;\n  cursor: help;\n}\n\n/* P4 \u95F8\u95E8\u53EF\u89C6\u5316\uFF1A\u91CC\u7A0B\u7891\u95F8\u95E8\u7528\u5B9E\u7EBF\u5F3A\u8C03\u8FB9\u6846\uFF08\u666E\u901A\u865A\u62DF\u8282\u70B9\u662F\u865A\u7EBF\uFF09 */\n.wf-node.is-gate {\n  border-style: solid;\n  border-color: var(--wf-brand);\n  box-shadow: 0 0 0 1px var(--wf-brand) inset;\n}\n\n.wf-node__proxy-badge.is-gate {\n  color: var(--wf-brand);\n  border-color: var(--wf-brand);\n}\n\n/* P4\uFF1A\u7236\u4EE3\u7406\u8865\u4E01\u6539\u52A8\u7684\u8282\u70B9\u89D2\u6807 */\n.wf-node__agent-badge {\n  flex: none;\n  font-size: 9px;\n  font-weight: 750;\n  color: var(--wf-brand);\n  border: 1px solid var(--wf-brand);\n  border-radius: 999px;\n  padding: 0 5px;\n  line-height: 15px;\n  opacity: .9;\n}\n\n.wf-node.is-locked {\n  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--wf-ink-2) 35%, transparent);\n}\n\n.wf-node.is-locked .wf-node__label {\n  opacity: .92;\n}\n\n.wf-node__prompt {\n  margin-top: 5px;\n  font-size: 11px;\n  color: var(--wf-ink-2);\n  white-space: pre-wrap;\n  max-height: 34px;\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical;\n}\n\n/* \u5361\u7247\u53F3\u4E0A\u89D2\u300C\u4EA4\u6362\u5DE6\u53F3\u8FDE\u63A5\u70B9\u300D\u6309\u94AE\uFF08\u7528\u6237\u6279\u6CE8\uFF1A\u7F8E\u5316\u5E03\u7EBF\u9632\u4EA4\u53C9\uFF1B\u4EA4\u6362\u540E\u8FDE\u7EBF\u7AEF\u70B9\u968F\u4E4B\u6362\u5411\uFF09 */\n.wf-node__swap {\n  position: absolute;\n  z-index: 5;\n  top: 7px;\n  right: 8px;\n  width: 22px;\n  height: 22px;\n  min-width: 22px;\n  padding: 0;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 7px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink-2);\n  font-size: 13px;\n  line-height: 1;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: border-color .14s ease, color .14s ease;\n}\n\n.wf-node__swap:hover {\n  border-color: var(--wf-brand);\n  color: var(--wf-brand);\n}\n\n.wf-node__swap.is-active {\n  border-color: var(--wf-brand);\n  color: var(--wf-brand);\n  background: color-mix(in srgb, var(--wf-brand) 10%, var(--wf-layer-2));\n}\n\n/* \u753B\u5E03\u5DE6\u4E0A\u89D2\u5DE5\u4F5C\u6D41\u540D\u79F0\u89D2\u6807\uFF08\u7528\u6237\u6279\u6CE8\uFF1A\u6A21\u677F/\u5B9E\u4F8B + \u540D\u79F0\uFF1B\u56FA\u5B9A\u4E0D\u968F\u7F29\u653E\u5E73\u79FB\uFF09 */\n.wf-canvas-caption {\n  position: absolute;\n  z-index: 7;\n  top: 12px;\n  left: 14px;\n  max-width: 46%;\n  padding: 5px 11px;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 9px;\n  background: var(--wf-layer);\n  color: var(--wf-ink-2);\n  font-size: 11px;\n  font-weight: 650;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  pointer-events: none;\n  box-shadow: 0 6px 16px color-mix(in srgb, var(--wf-ink) 8%, transparent);\n}\n\n.wf-canvas-caption strong {\n  color: var(--wf-ink);\n  font-weight: 720;\n}\n\n/* ---- \u6309\u8282\u70B9\u79CD\u7C7B\u7740\u8272\uFF08wf-node--<kind>\uFF09 ---- */\n.wf-node--parent .wf-node__kind {\n  color: var(--wf-brand);\n}\n\n.wf-node--agent .wf-node__kind {\n  color: var(--wf-brand);\n}\n\n.wf-node--file .wf-node__kind {\n  color: var(--wf-ink-2);\n}\n\n.wf-node--database .wf-node__kind {\n  color: var(--wf-database);\n}\n\n.wf-node--start .wf-node__kind {\n  color: var(--wf-ok);\n}\n\n.wf-node--end .wf-node__kind {\n  color: var(--wf-err);\n}\n\n.wf-node--pause .wf-node__kind {\n  color: var(--wf-warn);\n}\n\n.wf-node--group .wf-node__kind {\n  color: var(--wf-warn);\n}\n\n/* ---- \u534F\u4F5C\u7EC4\u5361\u7247 ---- */\n.wf-node--group {\n  display: flex;\n  flex-direction: column;\n  padding: 10px 12px;\n}\n\n.wf-group-node {\n  width: 300px;\n  height: 220px;\n}\n\n/* \u62D6\u62FD\u60AC\u505C\u5165\u7EC4\u9AD8\u4EAE\uFF08\u7528\u6237\u9A8C\u6536\u6807\u6CE8\uFF1A\u5361\u7247\u63D2\u5165\u534F\u4F5C\u7EC4\u5361\u7247\u533A\u57DF\u5373\u8BC6\u522B\u4E3A\u5165\u7EC4\uFF09 */\n.wf-group-node.is-drop-target .wf-node--group {\n  border-color: var(--wf-pass);\n  box-shadow: 0 0 0 3px color-mix(in srgb, var(--wf-pass) 26%, transparent), 0 0 22px color-mix(in srgb, var(--wf-pass) 32%, transparent);\n}\n\n.wf-group__drop-hint {\n  flex: none;\n  margin: 6px 0 2px;\n  padding: 4px 8px;\n  border: 1px dashed var(--wf-pass);\n  border-radius: 8px;\n  color: var(--wf-pass);\n  font-size: 10px;\n  font-weight: 700;\n  text-align: center;\n  pointer-events: none;\n}\n\n/* \u5DF2\u9009\u6587\u4EF6\u5217\u8868\uFF08\u6587\u4EF6\u8868\u5355\uFF0C\u6309\u94AE\u4E0B\u65B9\u663E\u793A\uFF1B\u7528\u6237\u9A8C\u6536\u6807\u6CE8\uFF09 */\n.wf-file-list {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  padding: 6px;\n  border: 1px solid var(--wf-border);\n  border-radius: 8px;\n  background: var(--wf-layer-2);\n  max-height: 120px;\n  overflow: auto;\n  scrollbar-width: thin;\n}\n\n.wf-file-chip {\n  display: block;\n  font-size: 11px;\n  color: var(--wf-ink);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  padding: 2px 6px;\n  border-radius: 6px;\n  background: color-mix(in srgb, var(--wf-brand) 8%, transparent);\n}\n\n/* ---- \u534F\u4F5C\u7EC4\u6210\u5458\u5217\u8868\uFF08\u7F29\u5C0F\u7248\u89D2\u8272\u5361\uFF09 ---- */\n.wf-group__members {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n  margin-top: 6px;\n  padding: 6px;\n  border: 1px solid var(--wf-border);\n  border-radius: 8px;\n  background: var(--wf-layer-2);\n  scrollbar-width: thin;\n}\n\n/* \u7EC4\u5185\u6210\u5458 = \u7F29\u5C0F\u7248\u89D2\u8272\u5361\uFF1A\u4EC5\u540D\u79F0+\u72B6\u6001\uFF0C\u6570\u636E\u5E93/\u4E0A\u4E0B\u6587\u63A5\u70B9\uFF0C\u65E0\u6D41\u7A0B\u63A5\u70B9\uFF08\u7528\u6237\u6279\u6CE8 Q2\uFF09 */\n.wf-group__member {\n  position: relative;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-height: 36px;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 8px;\n  background: color-mix(in srgb, var(--wf-layer) 90%, var(--wf-brand) 10%);\n  color: var(--wf-ink);\n  padding: 6px 10px;\n  font-size: 11px;\n  text-align: left;\n  box-shadow: 0 2px 6px color-mix(in srgb, var(--wf-ink) 8%, transparent);\n  transition: border-color .16s ease, box-shadow .16s ease;\n}\n\n.wf-group__member:hover {\n  border-color: color-mix(in srgb, var(--wf-brand) 55%, var(--wf-border-strong));\n  box-shadow: 0 2px 10px color-mix(in srgb, var(--wf-ink) 12%, transparent);\n}\n\n.wf-graph__handle--mini {\n  width: 9px;\n  height: 9px;\n  border-width: 1px;\n}\n\n.wf-graph__handle--mini:hover {\n  transform: translateY(-50%) scale(1.25);\n}\n\n.wf-group__member-name {\n  flex: 1;\n  min-width: 0;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  font-weight: 650;\n}\n\n.wf-group__member-status {\n  display: inline-flex;\n  align-items: center;\n  gap: 3px;\n  flex: none;\n  font-size: 10px;\n  color: var(--wf-ink-2);\n  padding: 1px 6px;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 6px;\n  background: color-mix(in srgb, var(--wf-layer) 92%, var(--wf-ink) 8%);\n}\n\n.wf-group__resize {\n  position: absolute;\n  z-index: 6;\n  right: -4px;\n  bottom: -4px;\n  width: 14px;\n  height: 14px;\n  border-right: 3px solid var(--wf-border-strong);\n  border-bottom: 3px solid var(--wf-border-strong);\n  border-radius: 0 0 6px 0;\n  cursor: nwse-resize;\n}\n\n.wf-group__resize:hover {\n  border-color: var(--wf-brand);\n}\n\n/* ---- \u753B\u5E03\u7A7A\u6001\u63D0\u793A ---- */\n.wf-canvas-empty {\n  position: absolute;\n  inset: 0;\n  display: grid;\n  place-items: center;\n  pointer-events: none;\n}\n\n.wf-canvas-empty__hint {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 10px;\n  color: var(--wf-ink-2);\n  font-size: 12px;\n  text-align: center;\n  opacity: .85;\n}\n\n.wf-canvas-empty__icon {\n  width: 52px;\n  height: 52px;\n  border: 1px dashed var(--wf-border-strong);\n  border-radius: 16px;\n  display: grid;\n  place-items: center;\n  font-size: 22px;\n  color: var(--wf-brand);\n}\n";
